const cfg = {};

for (const item of $input.all()) {
  const r = item.json;
  let v = r.valor;
  if (r.tipo === 'int') v = parseInt(v, 10);
  else if (r.tipo === 'decimal') v = parseFloat(v);
  else if (r.tipo === 'bool') v = v === '1' || v === 'true' || v === 1;
  cfg[r.chave] = v;
}

const obrigatorias = [
  'SCORE_MINIMO',
  'DIAS_SEM_REPETIR',
  'QUEDA_MINIMA_REPOST',
  'TOLERANCIA_PRECO',
  'MAX_TENTATIVAS',
  'AFILIADO_MODO',
  'CAPTION_MAX',
  'TELEGRAM_CHAT_ADMIN',
];

const faltando = obrigatorias.filter(
  (k) => cfg[k] === undefined || cfg[k] === null || cfg[k] === ''
);

if (faltando.length) {
  throw new Error(
    'Config vazia ou faltando: ' +
      faltando.join(', ') +
      '. Preencha na tabela config antes de ativar o publicador.'
  );
}

return [{ json: cfg }];

// Lock em duas camadas, camada 1: PRIMARY KEY em locks_execucao.
// ON DUPLICATE KEY so deixa tomar o lock se o anterior expirou,
// num unico statement (o node MySQL nao roda multi-statement por padrao).

const dono = 'exec-' + $execution.id;
const MINUTOS = 10;

const sqlAdquirir =
  "INSERT INTO locks_execucao (nome, dono, expira_em)\n" +
  "VALUES ('publicador', '" +
  dono.replace(/'/g, '') +
  "', DATE_ADD(NOW(), INTERVAL " +
  MINUTOS +
  " MINUTE))\n" +
  'ON DUPLICATE KEY UPDATE\n' +
  '  dono      = IF(expira_em <= NOW(), VALUES(dono), dono),\n' +
  '  criado_em = IF(expira_em <= NOW(), NOW(), criado_em),\n' +
  '  expira_em = IF(expira_em <= NOW(), VALUES(expira_em), expira_em)';

return [{ json: { dono, sqlAdquirir } }];

// O SELECT que concentra TODA a regra anti-repeticao:
//   score minimo + link cadastrado + janela de N dias
//   + queda minima de preco + retries pendentes
// Nao espalhar isso em IFs depois - e aqui que mora a decisao.

const cfg = $('Montar Config').first().json;

const scoreMin = parseInt(cfg.SCORE_MINIMO, 10);
const dias = parseInt(cfg.DIAS_SEM_REPETIR, 10);
const queda = parseFloat(cfg.QUEDA_MINIMA_REPOST);
const maxTent = parseInt(cfg.MAX_TENTATIVAS, 10);
const exigeLink = String(cfg.AFILIADO_MODO) === 'tabela';

if (![scoreMin, dias, maxTent].every(Number.isFinite) || !Number.isFinite(queda)) {
  throw new Error('Config numerica invalida no publicador.');
}

const fatorQueda = (1 - queda / 100).toFixed(4);

const sql =
  'SELECT\n' +
  '  o.id, o.produto_id, o.titulo, o.categoria_id,\n' +
  '  o.preco_atual, o.preco_original, o.desconto, o.frete_gratis,\n' +
  '  o.condicao, o.catalogo, o.vendidos, o.avaliacao,\n' +
  '  o.link_produto, o.imagem, o.score, o.status, o.tentativas,\n' +
  '  c.nome AS categoria, c.emoji, c.frase_padrao,\n' +
  '  la.url_afiliado\n' +
  'FROM ofertas o\n' +
  'LEFT JOIN categorias      c  ON c.id = o.categoria_id\n' +
  'LEFT JOIN links_afiliados la ON la.produto_id = o.produto_id\n' +
  'WHERE o.score >= ' +
  scoreMin +
  '\n' +
  '  AND (\n' +
  "        o.status IN ('NOVO','APROVADO')\n" +
  "     OR (o.status = 'ERRO'\n" +
  '         AND o.tentativas < ' +
  maxTent +
  '\n' +
  '         AND o.proxima_tentativa IS NOT NULL\n' +
  '         AND o.proxima_tentativa <= NOW())\n' +
  '      )\n' +
  (exigeLink ? '  AND la.produto_id IS NOT NULL\n' : '') +
  '  AND NOT EXISTS (\n' +
  '        SELECT 1 FROM ofertas h\n' +
  '        WHERE h.produto_id = o.produto_id\n' +
  "          AND h.status = 'ENVIADO'\n" +
  '          AND h.enviado_em >= DATE_SUB(NOW(), INTERVAL ' +
  dias +
  ' DAY)\n' +
  '          AND o.preco_atual > h.preco_atual * ' +
  fatorQueda +
  '\n' +
  '      )\n' +
  'ORDER BY o.score DESC, o.criado_em ASC\n' +
  'LIMIT 1';

return [{ json: { sql } }];

// Normaliza a linha do banco e decide se esta rodada precisa de aprovacao.
// Regra: previa so na PRIMEIRA passada (status NOVO). Se o status ja e
// APROVADO, o workflow E ja liberou - publica direto, senao vira loop.

const cfg = $('Montar Config').first().json;
const o = $input.first().json;

const modoAprovacao = cfg.MODO_APROVACAO === true || cfg.MODO_APROVACAO === 1;
const precisaAprovacao = modoAprovacao && o.status !== 'APROVADO';

return [
  {
    json: {
      oferta_id: Number(o.id),
      produto_id: o.produto_id,
      titulo: o.titulo,
      categoria_id: o.categoria_id,
      categoria: o.categoria || null,
      emoji: o.emoji || null,
      frase_padrao: o.frase_padrao || 'Confira essa oferta.',
      preco_banco: Number(o.preco_atual),
      preco_original: o.preco_original == null ? null : Number(o.preco_original),
      desconto: o.desconto == null ? null : Number(o.desconto),
      frete_gratis: Number(o.frete_gratis) === 1,
      condicao: o.condicao,
      score: Number(o.score),
      status_original: o.status,
      tentativas_antes: Number(o.tentativas),
      link_produto: o.link_produto,
      imagem_banco: o.imagem,
      url_afiliado: o.url_afiliado || null,
      precisa_aprovacao: precisaAprovacao,
      dono: $('Montar SQL Lock').first().json.dono,
    },
  },
];

// Camada 2 da concorrencia: reserva por status.
// Se outra execucao pegou a mesma linha no meio, affectedRows volta 0.

const o = $input.first().json;
const dono = String(o.dono).replace(/'/g, '');

const sql =
  "UPDATE ofertas\n" +
  "SET status = 'PROCESSANDO',\n" +
  "    lock_owner = '" +
  dono +
  "',\n" +
  '    tentativas = tentativas + 1\n' +
  'WHERE id = ' +
  Number(o.oferta_id) +
  "\n  AND status IN ('NOVO','APROVADO','ERRO')";

return [{ json: { sql } }];

// Revalidacao imediatamente antes de publicar: preco, status e estoque.
// Se o preco mudou mais que TOLERANCIA_PRECO, nao publica com numero velho.

const cfg = $('Montar Config').first().json;
const o = $('Preparar Oferta').first().json;
const item = $input.first().json;

const tolerancia = Number(cfg.TOLERANCIA_PRECO);

const r = { ...o, pode_publicar: false, motivo: null };

if (!item || item.error || !item.id) {
  r.motivo = 'Revalidacao falhou: /items/' + o.produto_id + ' nao respondeu item valido.';
  return [{ json: r }];
}

if (item.status && item.status !== 'active') {
  r.motivo = 'Anuncio nao esta ativo (status=' + item.status + ').';
  return [{ json: r }];
}

if (typeof item.available_quantity === 'number' && item.available_quantity <= 0) {
  r.motivo = 'Sem estoque disponivel.';
  return [{ json: r }];
}

const precoAgora = Number(item.price);
if (!Number.isFinite(precoAgora) || precoAgora <= 0) {
  r.motivo = 'Preco atual invalido na revalidacao.';
  return [{ json: r }];
}

const diferenca = Math.abs(precoAgora - o.preco_banco);
if (diferenca > tolerancia) {
  r.motivo =
    'Preco mudou: banco R$ ' +
    o.preco_banco.toFixed(2) +
    ' -> agora R$ ' +
    precoAgora.toFixed(2) +
    ' (tolerancia R$ ' +
    tolerancia.toFixed(2) +
    ').';
  return [{ json: r }];
}

// precos confirmados: dai pra frente usa SEMPRE o valor revalidado
const origAgora = Number(item.original_price);
const precoOriginal =
  Number.isFinite(origAgora) && origAgora > precoAgora ? origAgora : null;

const desconto = precoOriginal
  ? Math.round((1 - precoAgora / precoOriginal) * 100)
  : null;

let imagem = o.imagem_banco;
if (Array.isArray(item.pictures) && item.pictures.length) {
  const u = item.pictures[0].secure_url || item.pictures[0].url;
  if (u) imagem = String(u).replace('http://', 'https://');
}

r.pode_publicar = true;
r.preco_final = precoAgora;
r.preco_original_final = precoOriginal;
r.desconto_final = desconto;
r.imagem_final = imagem;
r.frete_gratis_final = !!(item.shipping && item.shipping.free_shipping);

return [{ json: r }];

// A IA escreve UMA frase de apoio e nada mais.
// Numero, preco e desconto sao montados pelo codigo - a IA nunca ve
// valor nenhum, justamente pra nao ter como inventar numero errado.

const o = $input.first().json;

const cfg = $('Montar Config').first().json;

const prompt =
  'Escreva UMA frase curta em portugues do Brasil recomendando este produto ' +
  'para um canal de ofertas.\n\n' +
  'Produto: ' +
  String(o.titulo).slice(0, 160) +
  '\n' +
  'Categoria: ' +
  (o.categoria || 'geral') +
  '\n\n' +
  'REGRAS OBRIGATORIAS:\n' +
  '- No maximo 140 caracteres.\n' +
  '- NAO escreva numeros, precos, porcentagens, R$ ou qualquer valor.\n' +
  '- NAO use palavras de urgencia (corre, ultimas, imperdivel, agora, rapido).\n' +
  '- No maximo 1 emoji.\n' +
  '- Tom simples e direto, sem exagero publicitario.\n' +
  '- Responda SOMENTE a frase, sem aspas e sem explicacao.';

return [
  {
    json: {
      modelo: cfg.IA_MODELO || 'gpt-4o-mini',
      prompt,
      ia_ativa: cfg.IA_ATIVA === true || cfg.IA_ATIVA === 1,
    },
  },
];

// Valida a frase da IA e devolve um payload NEUTRO (sem formatacao).
// Quem formata por plataforma e o node Formatar Por Destino.
// Reprova e cai na frase_padrao se vier:
//   numero | R$ | % | termo de urgencia | >3 emojis | >200 chars

const o = $('Conferir Preco').first().json;

// ---- 1. extrai a frase, se a IA rodou ---------------------------------
let frase = null;
let origemFrase = 'padrao';
const entrada = $input.first().json;

if (entrada && Array.isArray(entrada.choices) && entrada.choices.length) {
  const bruto = entrada.choices[0].message && entrada.choices[0].message.content;
  if (bruto) {
    frase = String(bruto).trim().replace(/^["']|["']$/g, '');
    origemFrase = 'ia';
  }
}

// ---- 2. valida ---------------------------------------------------------
const URGENCIA = /\b(corre|corra|ultimas?|ultima|imperdivel|imperd[ií]vel|agora|r[áa]pido|voando|aproveite|n[ãa]o perca|acaba|esgotando|relampago|rel[âa]mpago)\b/i;
const EMOJI = /[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{1F000}-\u{1F2FF}]/gu;

function reprovar(f) {
  if (!f) return 'vazia';
  if (f.length > 200) return 'maior que 200 caracteres';
  if (/\d/.test(f)) return 'contem numero';
  if (/R\$|\breais\b/i.test(f)) return 'contem preco';
  if (/%|por\s*cento/i.test(f)) return 'contem percentual';
  if (URGENCIA.test(f)) return 'contem termo de urgencia';
  const emojis = f.match(EMOJI);
  if (emojis && emojis.length > 3) return 'mais de 3 emojis';
  return null;
}

const motivoReprova = reprovar(frase);
if (motivoReprova) {
  console.log('Frase da IA reprovada (' + motivoReprova + '): ' + JSON.stringify(frase));
  frase = o.frase_padrao;
  origemFrase = 'padrao';
}

// ---- 3. render canonico em HTML ---------------------------------------
// Serve para a previa do admin (sempre Telegram) e para gravar em
// ofertas.mensagem como versao legivel. Os outros formatos saem do
// Formatar Por Destino, a partir das colunas + desta frase.
function brl(v) {
  return 'R$ ' + Number(v).toFixed(2).replace('.', ',');
}
function htmlEsc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const emoji = o.emoji ? o.emoji + ' ' : '';
let titulo = String(o.titulo).trim();
if (titulo.length > 95) titulo = titulo.slice(0, 92).trimEnd() + '...';

const l = [];
l.push(o.desconto_final != null
  ? '<b>' + emoji + o.desconto_final + '% OFF</b>'
  : '<b>' + emoji + (o.categoria || 'Oferta') + '</b>');
l.push('');
l.push('<b>' + htmlEsc(titulo) + '</b>');
l.push('');
if (o.preco_original_final != null) l.push('De <s>' + brl(o.preco_original_final) + '</s>');
l.push('Por <b>' + brl(o.preco_final) + '</b>');
if (o.frete_gratis_final) l.push('Frete gratis');
l.push('');
l.push(htmlEsc(frase));
l.push('');
l.push('<a href="' + o.url_afiliado + '">Ver no Mercado Livre</a>');
l.push('');
l.push('<i>Preco e estoque podem mudar a qualquer momento.</i>');

return [
  {
    json: {
      ...o,
      frase,
      titulo_curto: titulo,
      origem_frase: origemFrase,
      motivo_reprova: motivoReprova,
      mensagem_html: l.join('\n'),
    },
  },
];

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
  const s = String(v)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\u0000/g, '');
  return "'" + s + "'";
}

const o = $input.first().json;

// grava a mensagem e sincroniza o preco revalidado na linha
const sql =
  'UPDATE ofertas SET\n' +
  '  frase = ' +
  esc(o.frase) +
  ',\n' +
  '  mensagem = ' +
  esc(o.mensagem_html) +
  ',\n' +
  '  preco_atual = ' +
  Number(o.preco_final).toFixed(2) +
  ',\n' +
  '  preco_original = ' +
  (o.preco_original_final == null
    ? 'NULL'
    : Number(o.preco_original_final).toFixed(2)) +
  ',\n' +
  '  desconto = ' +
  (o.desconto_final == null ? 'NULL' : Number(o.desconto_final)) +
  ',\n' +
  '  imagem = ' +
  esc(o.imagem_final) +
  '\n' +
  'WHERE id = ' +
  Number(o.oferta_id);

return [{ json: { ...o, sql } }];

