parameters.jsCode:
// Retry escalonado: 1a falha +5 min, 2a +15 min, 3a para de tentar
// (o SELECT do publicador exige tentativas < MAX_TENTATIVAS).
// sem_retry = true vira DESCARTADO direto, sem nova tentativa.

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  const s = String(v)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/[\r\n]+/g, ' ')
    .slice(0, 240);
  return "'" + s + "'";
}

const o = $('Preparar Oferta').first().json;
const cfg = $('Montar Config').first().json;
const entrada = $input.first().json;

const motivo = entrada.motivo || 'Falha nao descrita.';
const semRetry = entrada.sem_retry === true;
const maxTent = parseInt(cfg.MAX_TENTATIVAS, 10) || 3;

// Reservar Produto ja fez tentativas = tentativas + 1
const tentativaAtual = Number(o.tentativas_antes) + 1;

let status;
let proxima;

if (semRetry) {
  status = 'DESCARTADO';
  proxima = 'NULL';
} else if (tentativaAtual >= maxTent) {
  status = 'ERRO';
  proxima = 'NULL';
} else {
  status = 'ERRO';
  const minutos = tentativaAtual === 1 ? 5 : 15;
  proxima = 'DATE_ADD(NOW(), INTERVAL ' + minutos + ' MINUTE)';
}

const sql =
  'UPDATE ofertas SET\n' +
  "  status = '" +
  status +
  "',\n" +
  '  motivo = ' +
  esc(motivo) +
  ',\n' +
  '  proxima_tentativa = ' +
  proxima +
  ',\n' +
  '  lock_owner = NULL\n' +
  'WHERE id = ' +
  Number(o.oferta_id);

return [
  {
    json: {
      sql,
      status,
      motivo,
      tentativa: tentativaAtual,
      max: maxTent,
      produto_id: o.produto_id,
      oferta_id: o.oferta_id,
    },
  },
];

