parameters.jsCode:
// Um item por destino ativo, com a mensagem ja renderizada no formato
// que aquela plataforma entende. Adicionar WhatsApp amanha = adicionar
// um render aqui + o node de envio; o resto do fluxo nao muda.

const o = $('Validar Frase').first().json;
const cfg = $('Montar Config').first().json;
const captionMax = parseInt(cfg.CAPTION_MAX, 10) || 1024;

const destinos = $input.all().map((i) => i.json).filter((d) => d && d.id);

function brl(v) {
  return 'R$ ' + Number(v).toFixed(2).replace('.', ',');
}

// --- html: Telegram parse_mode HTML -----------------------------------
function renderHtml() {
  return o.mensagem_html;
}

// --- markdown_wa: *negrito* _italico_ ~riscado~, link cru -------------
// O WhatsApp nao tem ancora com texto: a URL vai sozinha na linha.
function renderWa() {
  const emoji = o.emoji ? o.emoji + ' ' : '';
  const l = [];
  l.push(o.desconto_final != null
    ? '*' + emoji + o.desconto_final + '% OFF*'
    : '*' + emoji + (o.categoria || 'Oferta') + '*');
  l.push('');
  l.push('*' + o.titulo_curto + '*');
  l.push('');
  if (o.preco_original_final != null) l.push('De ~' + brl(o.preco_original_final) + '~');
  l.push('Por *' + brl(o.preco_final) + '*');
  if (o.frete_gratis_final) l.push('Frete gratis');
  l.push('');
  l.push(o.frase);
  l.push('');
  l.push(o.url_afiliado);
  l.push('');
  l.push('_Preco e estoque podem mudar a qualquer momento._');
  return l.join('\n');
}

// --- texto: sem formatacao nenhuma ------------------------------------
function renderTexto() {
  const l = [];
  l.push(o.desconto_final != null
    ? o.desconto_final + '% OFF'
    : (o.categoria || 'Oferta'));
  l.push('');
  l.push(o.titulo_curto);
  l.push('');
  if (o.preco_original_final != null) l.push('De ' + brl(o.preco_original_final));
  l.push('Por ' + brl(o.preco_final));
  if (o.frete_gratis_final) l.push('Frete gratis');
  l.push('');
  l.push(o.frase);
  l.push('');
  l.push(o.url_afiliado);
  return l.join('\n');
}

const RENDER = { html: renderHtml, markdown_wa: renderWa, texto: renderTexto };

// So o Telegram tem node de envio montado neste workflow.
const IMPLEMENTADAS = ['telegram'];

return destinos.map((d) => {
  const fn = RENDER[d.formato] || renderTexto;
  let msg = fn();

  if (msg.length > captionMax) {
    msg = msg.slice(0, captionMax - 40).trimEnd() + '...\n\n' + o.url_afiliado;
    console.log('Mensagem truncada para ' + d.nome + ' (limite ' + captionMax + ').');
  }

  return {
    json: {
      oferta_id: o.oferta_id,
      destino_id: Number(d.id),
      destino_nome: d.nome,
      plataforma: d.plataforma,
      destino: d.destino,
      formato: d.formato,
      implementado: IMPLEMENTADAS.includes(d.plataforma),
      imagem: o.imagem_final,
      mensagem: msg,
      tamanho: msg.length,
    },
  };
});

// Le o resultado do envio. Com onError continueRegularOutput, a falha
// chega como item normal com a chave error - por isso da pra registrar
// destino por destino em vez de derrubar a execucao toda.

const d = $('Formatar Por Destino').item.json;
const r = $json;

const falhou = !!(r && r.error);
let erro = null;
if (falhou) {
  const e = r.error;
  erro = String((e && (e.message || e.description)) || e).slice(0, 480);
}

return {
  json: {
    oferta_id: d.oferta_id,
    destino_id: d.destino_id,
    destino_nome: d.destino_nome,
    status: falhou ? 'ERRO' : 'OK',
    erro,
  },
};

// Destino ativo numa plataforma que ainda nao tem node de envio aqui.
// Registra como ERRO para aparecer em vw_envios_por_destino, em vez de
// sumir em silencio.

const d = $json;

return {
  json: {
    oferta_id: d.oferta_id,
    destino_id: d.destino_id,
    destino_nome: d.destino_nome,
    status: 'ERRO',
    erro: 'Plataforma ' + d.plataforma + ' ativa em destinos mas sem node de envio no publicador.',
  },
};

// Consolida o fan-out: um INSERT com todas as linhas de envios_destino
// e decide o status final da oferta.
// ofertas.status = ENVIADO se pelo menos um destino aceitou.

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  const s = String(v)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/[\r\n]+/g, ' ')
    .slice(0, 480);
  return "'" + s + "'";
}

const itens = $input.all().map((i) => i.json);

if (!itens.length) {
  throw new Error('Consolidar Envios recebeu zero itens - nenhum destino processado.');
}

const ofertaId = Number(itens[0].oferta_id);
const ok = itens.filter((i) => i.status === 'OK');
const erro = itens.filter((i) => i.status !== 'OK');

const linhas = itens.map(
  (i) =>
    '(' +
    [Number(i.oferta_id), Number(i.destino_id), esc(i.status), esc(i.erro)].join(', ') +
    ')'
);

const sqlEnvios =
  'INSERT INTO envios_destino (oferta_id, destino_id, status, erro)\nVALUES\n  ' +
  linhas.join(',\n  ') +
  '\nON DUPLICATE KEY UPDATE\n' +
  '  status = VALUES(status),\n' +
  '  erro = VALUES(erro),\n' +
  '  enviado_em = NOW()';

const algumOk = ok.length > 0;

const resumo =
  ok.length + ' destino(s) ok, ' + erro.length + ' com erro' +
  (erro.length ? ': ' + erro.map((e) => e.destino_nome).join(', ') : '');

const sqlOferta = algumOk
  ? "UPDATE ofertas SET\n" +
    "  status = 'ENVIADO',\n" +
    '  enviado_em = NOW(),\n' +
    '  lock_owner = NULL,\n' +
    '  motivo = ' + (erro.length ? esc('parcial: ' + resumo) : 'NULL') + ',\n' +
    '  proxima_tentativa = NULL\n' +
    'WHERE id = ' + ofertaId
  : "UPDATE ofertas SET\n" +
    "  status = 'ERRO',\n" +
    '  motivo = ' + esc('nenhum destino aceitou: ' + resumo) + ',\n' +
    '  proxima_tentativa = DATE_ADD(NOW(), INTERVAL 15 MINUTE),\n' +
    '  lock_owner = NULL\n' +
    'WHERE id = ' + ofertaId;

return [
  {
    json: {
      sqlEnvios,
      sqlOferta,
      oferta_id: ofertaId,
      algum_ok: algumOk,
      total: itens.length,
      ok: ok.length,
      erros: erro.length,
      resumo,
    },
  },
];
